export const BODY: string = "\n<p>مغير حجم الصور يغيّر أبعاد صورة أو رسم بالبكسلات: صورة تبدأ بـ4000 في 3000 بكسل قد تصبح 1200 في 900 أو 800 في 600 أو أي حجم آخر تحتاجه.</p>\n<p>الحجم مهم لأن كل وجهة تقريبًا تتوقع أبعادًا محددة: صورة رئيسية لموقع يجب أن تكون واسعة، وصورة شخصية يجب أن تكون مربعة، وقائمة سوق تحتاج صورًا بأبعاد معينة.</p>\n<p>يشرح هذا الدليل ما يفعله تغيير الحجم وكيف تعمل البكسلات والنسب المئوية وما يحميه قفل نسبة العرض إلى الارتفاع وكيف تعامل أوضاع الملاءمة صورًا لا تطابق شكل الهدف.</p>\n<h2 id=\"what-is-an-image-resizer\">ما مغير حجم الصور؟</h2>\n<p>مغير حجم الصور أداة تعيد بناء صورة بأبعاد جديدة بالبكسلات: يقرأ البكسلات الأصلية ويوزعها في شبكة جديدة بالحجم المختار ويعيد أخذ عينات التفاصيل لتناسب.</p>\n<p>تغيير الحجم مختلف عن تكبير العرض: عند التكبير يتغير فقط كم تبدو الصورة كبيرة على الشاشة، بينما يبقى الملف نفسه: وعند تغيير الحجم يتغير الملف نفسه، فتتغير أبعاده وحجم ملفه. وهو مختلف أيضًا عن القص: القص يقطع حواف صورة لتغيير شكلها، بينما تغيير الحجم يحافظ على الصورة كلها ويقيس كل ما فيها: صورة مغيرة الحجم تحتفظ بكل محتواها، فقط أصغر أو أكبر.</p>\n<p>ومغير حجم هذا الموقع يعمل تمامًا في متصفحك: صورك تُرسم على لوحة HTML5 على جهازك ولا تُرفع أبدًا إلى أي خادم: ذلك يبقي صورًا شخصية وصور منتجات غير منشورة خاصة.</p>\n<h2 id=\"pixels-dimensions-and-resolution\">البكسلات والأبعاد والدقة</h2>\n<p>كل صورة رقمية شبكة مربعات لون صغيرة تسمى بكسلات: أبعاد صورة هي عدد تلك المربعات عرضًا وارتفاعًا، مكتوبة كعرض في ارتفاع.</p>\n<p>الدقة غالبًا تُخلط بالأبعاد، لكنهما ليستا نفس الشيء: الأبعاد تقول كم بكسلًا في صورة، بينما الدقة تقول كم تلك البكسلات مضغوطة عند الطباعة: وبكسلات أكثر تعني تفاصيل أكثر وملفًا أكبر: صورة بعرض 4000 بكسل تُظهر ملمسًا دقيقًا عند عرضها كبيرة، لكنها أكبر بكثير مما تحتاجه صفحة ويب.</p>\n<p>وتقليصها إلى عرض 1200 بكسل يتخلص من تفاصيل لا يستطيع أحد رؤيتها بحجم الشاشة ذلك، ويصبح الملف أصغر بكثير.</p>\n<p>ذلك المقايضة هو معنى تغيير الحجم: تطابق عدد البكسلات مع حيث ستُرى الصورة، محافظًا على تفاصيل كافية لتلك الشاشة ولا شيء أكثر: وصورة تُعرض صغيرة لا تحتاج بكسلات صورة كبيرة.</p>\n<h2 id=\"by-pixels-vs-by-percentage\">بالبكسلات أم بالنسبة المئوية</h2>\n<p>يوفر مغير الحجم طريقتين لتثبيت الحجم الجديد: بالبكسلات يتيح لك كتابة عرض وارتفاع دقيقين، حتى 12,000 بكسل لكل جانب: هذا هو الوضع المناسب عندما يكون الوجهة دقيقة.</p>\n<p>وبالنسبة المئوية يقيس الصورة نسبة إلى حجمها، من 10 بالمئة إلى 200 بالمئة: تستطيع سحب المنزلق أو لمس زر سريع لـ25 أو 50 أو 75 أو 150 أو 200 بالمئة: هذا الوضع مثالي عندما تعرف كم تريد تقليصًا نسبيًا لا حجمًا مطلقًا. ووضع النسبة المئوية هو أيضًا أبسط طريقة لتقليص دفعة صور متنوعة إلى النصف: كل صورة تقل بنفس النسبة، فصورة 4000 بكسل تصبح 2000 وصورة 2000 تصبح 1000.</p>\n<p>اختر بكسلات عندما يكون الوجهة دقيقًا ونسبة مئوية عندما يكون الهدف نسبيًا: سوق يطلب 1000 في 1000 يحتاج بكسلات، بينما مجلد صور كاميرا يحتاج فقط تصغيرًا عامًا يناسبه نسبة مئوية.</p>\n<h2 id=\"aspect-ratio-explained\">نسبة العرض إلى الارتفاع موضحة</h2>\n<p>نسبة العرض إلى الارتفاع هي العلاقة بين العرض والارتفاع: صورة 4000 في 3000 لها نسبة 4 إلى 3، بينما شاشة 1920 في 1080 لها نسبة 16 إلى 9: والنسبة تصف الشكل لا الحجم.</p>\n<p>عندما يكون خيار \"نسبة العرض إلى الارتفاع مقفلة\" مفعّلًا، كتابة عرض جديد يحدّث الارتفاع تلقائيًا بالنسبة الدقيقة: صورة 4000 في 3000 مغيرة إلى عرض 1200 تحصل على ارتفاع 900 تلقائيًا. وقفل النسبة هو الخيار الآمن الافتراضي في كل تغيير حجم تقريبًا: يحمي الوجوه من الاتساع والدوائر من التحول إلى أشكال بيضاوية والمنتجات من الظهور مسحوقة.</p>\n<p>وفك قفل النسبة يتيح لك كتابة العرض والارتفاع منفصلين، وهناك تظهر أوضاع الملاءمة: ذلك ينفع عندما يطلب وجهة إطارًا دقيقًا، لكنه أيضًا حيث يحدث التشوه.</p>\n<h2 id=\"fit-modes-contain-cover-stretch\">أوضاع الملاءمة: احتواء وتغطية ومد</h2>\n<p>احتواء يلائم الصورة كلها داخل إطار الهدف دون قص أي شيء: الشخص الكامل ينجو والمساحة الزائدة تصبح حشوًا حوله: استخدم احتواء عندما لا يُفقد شيء.</p>\n<p>وتغطية تملأ إطار الهدف من حافة إلى حافة بقص الزائد من الجانبين: يمتلئ الإطار تمامًا، لكن تُقص الحواف الخارجية للصورة: استخدم تغطية عندما يجب أن يمتلئ الإطار. ومد دقيق يجبر الصورة على الوصول إلى الحدود الدقيقة بالبكسلات، بغض النظر عن الشكل الذي بدأت به: لا يُقص شيء، لكن الصورة تُمد لتناسب، فالأشخاص قد يتسعون والمباني قد تطول.</p>\n<p>استخدمه فقط عندما يكون مطابقة الحدود الثابتة أهم من الحفاظ على النسب الحقيقية.</p>\n<p>معظم تغييرات الحجم اليومية لا تحتاج أي وضع ملاءمة، لأن قفل نسبة العرض إلى الارتفاع يتعامل مع الشكل: وأوضاع الملاءمة تظهر فقط عندما تفك النسبة أو تختار قالبًا بشكل مختلف عن صورتك: وعندما تظهر، احتواء هو الخيار الحكيم وتغطية هو الخيار الجريء.</p>\n<h2 id=\"social-and-screen-presets\">قوالب لوسائل التواصل الاجتماعي والشاشات</h2>\n<p>القوالب أحجام بنقرة واحدة للأماكن التي ينشر فيها الناس أكثر: عند النقر على قالب، تتحول الأداة إلى وضع بالبكسلات وتملأ الأبعاد الدقيقة، فتستطيع التصدير فورًا.</p>\n<p>القوالب المدمجة تغطي منشور إنستغرام 1080 في 1080 وقصة إنستغرام 1080 في 1920 ومصغرة يوتيوب 1280 في 720 وغلاف فيسبوك 851 في 315 وترويسة تويتر 1500 في 500: وكل منها يقابل وجهة حقيقية، فتصل الصورة بالحجم الذي يعرضه ذلك الوجهة أفضل.</p>\n<p>ولرؤية خطوة بخطوة كيف تستخدم هذه القوالب، اقرأ <a href=\"/ar/blog/kayfiyya-taghyir-hajm-as-sura/\">كيف تغيّر حجم صورة عبر الإنترنت</a>. ولتغيير حجم مجلد كامل بنفس القالب، اقرأ <a href=\"/ar/blog/dalil-taghyir-hajm-as-suwar-al-jumli/\">مغير حجم الصور الجملي: دليل كامل</a>.</p>\n<h2 id=\"formats-quality-and-transparency\">الصيغ والجودة والشفافية</h2>\n<p>تغيير الحجم والتحويل قد يحدثان في نفس التمريرة: صيغة الإخراج قد تبقى \"أصلية\" أو تتغير إلى JPG أو PNG أو WebP، مع منزلق جودة من 10 بالمئة إلى 100 بالمئة: ذلك يتيح لك تغيير الحجم والتحويل في خطوة واحدة.</p>\n<p>الجودة الافتراضية 85 بالمئة توازن حواف حادة وتدرجات نظيفة مع ملفات صغيرة لمواقع ومدونات وأسواق. واخفض نحو 65 أو 75 بالمئة عندما تحتاج توفيرًا أكثر، أو ارفع نحو 95 أو 100 بالمئة عندما تجهّز صورة للطباعة: تغييرات جودة صغيرة تحدث فرقًا كبيرًا في حجم الملف.</p>\n<p>والشفافية تحتاج عناية: تُحفظ عندما تحافظ على الصيغة \"أصلية\" في PNG أو WebP، أو عندما تختار صراحة PNG أو WebP كمخرج: وعند التغيير إلى JPG، تُملأ المناطق الشفافة بلون صلب.</p>\n<p>واحذر مفاجأة: تحويل JPG مضغوط إلى PNG دون فقدان أثناء تغيير الحجم قد يجعل الملف يزن بايتات أكثر مع أن البكسلات قلّت.</p>\n<p>PNG يحفظ بيانات البكسلات دون فقدان وخامًا، فقد يزن أكثر من JPEG الأصلي: ولملفات ويب صغيرة، اختر WebP أو JPG بجودة 80 إلى 85 بالمئة.</p>\n<h2 id=\"batch-resizing\">تغيير حجم دفعة</h2>\n<p>مغير الحجم يتعامل مع أكثر من صورة معًا: تستطيع إسقاط مجموعة صور كاملة في قائمة وتطبيق نفس الحجم على كلها وتنزيل النتائج واحدة واحدة أو في ملف ZIP واحد.</p>\n<p>مع نسبة العرض إلى الارتفاع مقفلة، تحافظ كل صورة في دفعة على نسبها الطبيعية، مستخدمة حد العرض بدل تشويه بورتريهات في إطارات أفقية: مجلد صور مختلطة يخرج كلها بعرض صحيح دون تشوه. وإذا احتجت أبعادًا متطابقة في الدفعة كلها، افتح النسبة واختر احتواء أو تغطية: ذلك هو القرار الصحيح لشبكة منتجات أو معرض حيث كل بلاطة يجب أن تطابق.</p>\n<p>ولدفعات كبيرة، استخدم <a href=\"/ar/taghyir-hajm-jumli-lis-suwar/\">مغير حجم الصور الجملي</a>: يعالج مجلدات كاملة بنفس القواعد.</p>\n<h2 id=\"enlarging-images\">تكبير صور</h2>\n<p>تستطيع تكبير صورة صغيرة بكتابة قيم بكسلات أكبر أو القياس حتى 200 بالمئة في وضع بالنسبة المئوية: اللوحة تمد البكسلات الموجودة لملء الحجم الجديد، لكن لا تفاصيل جديدة تُخلق.</p>\n<p>تكبير رسم بدقة منخفضة يجعل حوافه تبدو أنعم، لأن نفس المعلومات تُوزع على بكسلات أكثر: شعار صغير مكبر أربع مرات سيبدو ضبابيًا، مهما كان حادًا أصلًا. ولهذا التقليص آمن دائمًا تقريبًا والتكبير مقايضة: ابدأ بأكبر أصل لديك وقلّص إلى كل حجم تحتاجه: وإذا كانت نسختك الوحيدة صغيرة، أبقِها صغيرة أو اقبل بعض النعومة.</p>\n<p>وعرض \"مقارنة\" يُظهر الأبعاد الأصلية والمغيرة الحجم جنبًا إلى جنب، مع منزلق مقسم لمراجعة التفاصيل الدقيقة: استخدمه بعد أي تكبير وبعد أي تقليص كبير.</p>\n<h2 id=\"resizing-vs-cropping\">تغيير الحجم أم القص</h2>\n<p>تغيير الحجم والقص يحلان مشكلتين مختلفتين، وخلطهما يسبب معظم الإحباط عند تغيير الحجم: غيّر الحجم عندما تكون الصورة كلها جيدة لكن الحجم خطأ: وقص عندما يكون التأطير خطأ.</p>\n<p>صورة واسعة جدًا لمنشور مربع تحتاج قصًا لا تغيير حجم، لأن تغيير حجم صورة واسعة إلى إطار مربع سيسحقها: وصورة بالشكل الصحيح لكن بأبعاد خطأ تحتاج تغيير حجم لا قصًا. والأداتان تعملان جيدًا معًا: قص أولًا للحصول على الشكل الصحيح ثم غيّر الحجم للحصول على الأبعاد الصحيحة: و<a href=\"/ar/qass-as-suwar/\">قصاص الصور</a> قد يجهّز الشكل، ومغير الحجم ينهي المهمة.</p>\n<h2 id=\"resizing-vs-compressing\">تغيير الحجم أم الضغط</h2>\n<p>تغيير الحجم يغيّر كم بكسلًا في صورة، بينما الضغط يغيّر كم كفاءة حفظ تلك البكسلات: صورة مغيرة الحجم لها بكسلات أقل لحفظها، فملفها أصغر.</p>\n<p>وأي خطوة وحدها قد تصغّر ملفًا، لكن معًا تصغّرانه أكثر بكثير.</p>\n<p>صورة 4000 بكسل مضغوطة وحدها تبقى صورة 4000 بكسل، وصورة 1200 بكسل محفوظة بأقصى جودة تبقى أثقل مما يلزم: غيّر الحجم أولًا ثم اضغط: المقارنة الكاملة، مع ترتيب الخطوات ومتى تكفي واحدة وحدها، في <a href=\"/ar/blog/taghyir-al-hajm-vs-daght-as-sura/\">تغيير الحجم أم الضغط: ما الفرق؟</a>. وإذا كان هدفك فقط ملفًا أصغر بنفس الأبعاد، فالضغط وحده يكفي: استخدم <a href=\"/ar/\">ضاغط الصور</a>.</p>\n<h2 id=\"common-mistakes\">أخطاء شائعة</h2>\n<p>أكثر خطأ شيوعًا تغيير الحجم من نسخة صغيرة بدل الأصل: كل تغيير حجم يتخلص من بعض المعلومات، فالبدء بأكبر ملف لديك يعطي أفضل نتيجة.</p>\n<p>والخطأ الثاني فك قفل نسبة العرض إلى الارتفاع دون اختيار وضع ملاءمة عمدًا.</p>\n<p>تغيير حجم غير مقفل بمد دقيق يجعل الأشخاص أعرض والمباني أطول، والتشوه سهل تفويته في مصغرة: راجع القفل قبل التصدير. والخطأ الثالث حفظ كل صور مغيرة الحجم كـPNG: PNG دون فقدان وممتاز لرسوم بحواف حادة، لكنه ثقيل للصور: صورة مغيرة الحجم محفوظة كـPNG قد تزن أكثر من الأصل.</p>\n<p>والخطأ الرابع تغيير الحجم مرة والثقة عمياء: افتح عرض \"مقارنة\" وانظر إلى النص والوجوه وراجع حجم الملف قبل الرفع: مراجعة عشر ثوانٍ تكشف تشوهًا أو ضبابية قد تكلفك إعادة عمل.</p>\n<h2 id=\"quick-checklist\">قائمة تحقق سريعة</h2>\n<p>قبل تغيير الحجم، اعرف حجم الوجهة وأبقِ نسبة العرض إلى الارتفاع مقفلة ما لم يحتاج قالب أو وضع ملاءمة فكها وابدأ بأكبر أصل: وبعد تغيير الحجم، قارن الحدة وراجع حجم الملف.</p>\n<p>للخطوات العملية، اقرأ <a href=\"/ar/blog/kayfiyya-taghyir-hajm-as-sura/\">كيف تغيّر حجم صورة عبر الإنترنت</a>، وللقرار بين تغيير الحجم أو الضغط، اقرأ <a href=\"/ar/blog/taghyir-al-hajm-vs-daght-as-sura/\">تغيير الحجم أم الضغط: ما الفرق؟</a>. وافتح <a href=\"/ar/taghyir-hajm-as-suwar/\">مغير حجم الصور</a> لتطبيق كل ما سبق.</p>\n<ul>\n<li>حجم الوجهة معروف: بكسلات دقيقة أو نسبة مئوية مناسبة للغرض.</li>\n<li>نسبة العرض إلى الارتفاع مقفلة، ما لم يحتاج قالب أو وضع ملاءمة فكها.</li>\n<li>صيغة الإخراج مختارة: أصلية أو JPG أو PNG أو WebP، بجودة قريبة من 85 بالمئة.</li>\n<li>النتيجة رُوجعت في عرض \"مقارنة\" لتأكيد الحدة والنسب الحقيقية.</li>\n<li>الدفعة نُزّلت كـZIP عندما غُيّر حجم صورتين أو أكثر معًا.</li>\n</ul>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ماذا يغيّر تغيير حجم صورة فعلًا؟","answer":"تغيير الحجم يغيّر أبعاد صورة بالبكسلات، مثل تحويل صورة 4000 في 3000 إلى 1200 في 900: الشخص والألوان والتكوين تبقى، لكن الصورة لها بكسلات أقل وملف أصغر."},{"question":"هل أحتاج تثبيت برنامج لتغيير حجم صورة؟","answer":"لا، يعمل مغير الحجم تمامًا في متصفحك، فلا شيء لتنزيله ولا تثبيته: افتح صفحة مغير حجم الصور وأسقط صورتك واختر بكسلات أو نسبة مئوية ونزّل النتيجة."},{"question":"إلى أي حجم يجب أن أغيّر صورة لموقع؟","answer":"طابق الحجم مع حيث ستظهر الصورة: صورة محتوى مدونة غالبًا جيدة بعرض 1200 بكسل، وصورة رئيسية بعرض 1920 بكسل، ومصغرة بعرض 600 بكسل. وراجع متطلبات موقعك قبل التصدير."},{"question":"هل أستطيع تغيير حجم صورة دون فقدان جودة؟","answer":"تقليص صورة آمن عادة، لأن التفصيل المزال لن يُرى أصلًا بحجم العرض الأصغر: ويصبح فقدان الجودة مرئيًا خاصة عند تكبير صورة صغيرة، لأن البكسلات الموجودة تُمد لتغطية مساحة أكبر."},{"question":"هل أغيّر الحجم قبل القص أم بعده؟","answer":"قص أولًا ثم غيّر الحجم: القص يثبّت الشكل ويزيل الأجزاء التي لا تريدها، وتغيير الحجم بعدها يقيس النتيجة المقصوصة إلى الأبعاد الدقيقة بالبكسلات. وتغيير الحجم أولًا ثم القص يهدر بكسلات."},{"question":"هل أستطيع تغيير حجم صورة لطباعتها؟","answer":"نعم، لكن الطباعة تهتم بعدد البكسلات عند حجم طباعة معين، لا فقط بالأبعاد على الشاشة: صورة مطبوعة عند 300 نقطة في البوصة تحتاج 300 بكسل لكل بوصة طباعة، فراجع حساب الطباعة أولًا."}];
